import{z as l,x as s,o as e,c as A,q as t,j as i,D as E,d as n,s as o,S as r}from"./chunks/framework.C8m1ZpeB.js";const q=JSON.parse('{"title":"涨跌停与流动性黑洞","description":"","frontmatter":{"title":"涨跌停与流动性黑洞","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/cn-limit-liquidity-hole.md","filePath":"quant/cn-limit-liquidity-hole.md","lastUpdated":1791063341000}'),d={name:"quant/cn-limit-liquidity-hole.md"};function p(h,a,m,c,u,_){const B=s("Mermaid");return e(),A("div",null,[a[2]||(a[2]=t('<h1 id="涨跌停与流动性黑洞" tabindex="-1">涨跌停与流动性黑洞 <a class="header-anchor" href="#涨跌停与流动性黑洞" aria-label="Permalink to &quot;涨跌停与流动性黑洞&quot;">​</a></h1><div class="epigraph"><p>价格打在涨跌停上，一侧队列消失，连续竞价不再出清；流动性不是变贵，是暂时为零。次日开盘集合竞价承接未完成的发现，收盘价可以是配给而不是可买价。</p><footer>—— 《上海证券交易所交易规则》涨跌幅限制与集合竞价；Kim and Rhee, Price Limit Performance, Journal of Finance, 1997；对照[涨跌停与集合竞价](/quant/cn-limit-auction)、[邻近效应](/quant/cn-limit-proximity)</footer></div><p><a href="/quant/cn-ipo-registration">上一课</a>写了前五日无走廊。本课回到<strong>日常涨跌停</strong>：规则课已写如何生成开盘价与锁定板；邻近课已写距离走廊的截面状态。本课的缺口是<strong>流动性黑洞</strong>：锁定后 Kyle 深度塌缩、磁吸与延迟发现、以及组合缺腿。2015 年股灾中连续跌停使减仓与对冲同时失败，是制度路径而不是「波动率估错」。不重写集合竞价最大成交量规则。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无涨跌幅时，大单沿<a href="/quant/lob-structure">LOB</a> 扫档，冲击有限。有涨跌幅时，意愿价格越出走廊，申报堆在停板价，对手方消失。买方在涨停、卖方在跌停面对的是配给：时间优先排队，成交不是保证。用停板收盘价计算组合收益，是把未成交当成成交。问题是把「可成交标志」写成收益的乘数：锁定且你处于错误一侧，当日收益不可实现，风险滚到次日开盘——而次日仍可能继续锁定。</p><p>Kim 与 Rhee（1997）等价格限制文献讨论磁吸与冷却。A 股证据更常支持延迟发现：触及后次日同向跳开。因子与止损必须把走廊当硬约束。黑洞还传染：股票跌停、期货与 ETF 仍交易，基差与折溢价爆炸，中性与期现缺腿。</p><h3 id="_2015-年的路径" tabindex="-1">2015 年的路径 <a class="header-anchor" href="#_2015-年的路径" aria-label="Permalink to &quot;2015 年的路径&quot;">​</a></h3><p>高杠杆融资盘在跌停板上无法平仓，担保比例击穿，强平单堆在同一侧，流动性供给进一步撤退。这与国际闪电崩盘的空簿路径同族，但触发器是涨跌停配给 + 两融，而不是单纯的 E-mini 市价单。回测「2015 年市场中性」若假设跌停可卖，净值是假的。</p>',8)),(e(),i(r,null,{default:E(()=>[o(B,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20LEV%5B%22%E9%AB%98%E6%9D%A0%E6%9D%86%E8%9E%8D%E8%B5%84%E7%9B%98%22%5D%20--%3E%20DROP%5B%22%E8%82%A1%E4%BB%B7%E4%B8%8B%E6%8E%A2%E6%8E%A5%E8%BF%91%E8%B7%8C%E5%81%9C%22%5D%0A%20%20DROP%20--%3E%20MGN%5B%22%E6%8B%85%E4%BF%9D%E6%AF%94%E4%BE%8B%E5%87%BB%E7%A9%BF%EF%BC%9A%E8%BF%BD%E4%BF%9D%E6%88%96%E5%BC%BA%E5%B9%B3%22%5D%0A%20%20MGN%20--%3E%20SELLQ%5B%22%E5%BC%BA%E5%B9%B3%E5%8D%96%E5%8D%95%E5%A0%86%E5%9C%A8%E8%B7%8C%E5%81%9C%E4%BB%B7%22%5D%0A%20%20SELLQ%20--%3E%20NOBUY%5B%22%E8%B7%8C%E5%81%9C%E9%94%81%E6%AD%BB%EF%BC%9A%E5%8D%96%E4%B8%8D%E5%87%BA%E5%8E%BB%22%5D%0A%20%20NOBUY%20--%3E%20WORSE%5B%22%E6%8B%85%E4%BF%9D%E8%BF%9B%E4%B8%80%E6%AD%A5%E6%81%B6%E5%8C%96%20%E2%86%92%20%E6%9B%B4%E5%A4%9A%E5%BC%BA%E5%B9%B3%22%5D%0A%20%20WORSE%20--%3E%20SELLQ%0A%20%20RETREAT%5B%22%E6%B5%81%E5%8A%A8%E6%80%A7%E4%BE%9B%E7%BB%99%E6%92%A4%E9%80%80%22%5D%20--%3E%20DROP%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p><span class="marginnote">术语翻译：「磁吸效应」就是价格越接近涨跌停，越多人抢着往停板方向交易——想买的怕明天高开追不进，想卖的怕明天跌停卖不出，抢本身把价格推到板上，像磁铁把价格吸过去。它和「冷却假说」说的是相反的两种可能。</span></p><p><span class="marginnote">主板 10%、科创/创业 20%、注册制前五日不设限、ST 历史 5% 与 2026 年修订后的变化，必须按生效日切换。统一「涨跌停哑元」会在 20% 板上漏锁。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>状态：连续 / 涨停锁定 / 跌停锁定 / 集合竞价 / 停牌。收益：仅在可成交方向与可成交量上实现；否则持有到下一可成交拍卖。冲击模型在锁定日对错误一侧取无穷或拒绝下单。组合优化加入「不允许增加锁定方向的需求」。对冲：期货腿单独风控，缺腿日报告净暴露。</p><p><span class="marginnote">直觉类比：锁定板上的排队像一条只剩一个窗口的银行队伍——不是业务办不了，而是只有一个方向能办；你排在第 5000 位，明天窗口还可能继续只开这一侧。风险没有消失，只是被配给延迟到下一场拍卖。</span></p><p>邻近度特征可用于预测锁定概率，见邻近课；本课要求执行层读取同一状态，而不是只在因子里当 alpha。容量：停板日 ADV 的历史均值高估可用流动性——可用是零。</p><h3 id="开盘集合竞价是泄洪" tabindex="-1">开盘集合竞价是泄洪 <a class="header-anchor" href="#开盘集合竞价是泄洪" aria-label="Permalink to &quot;开盘集合竞价是泄洪&quot;">​</a></h3><p>未完成发现在 9:15–9:25（及不可撤时段）释放。虚拟参考价不是可成交保证。用 9:24 的虚拟价当 9:21 的决策是未来函数。收盘集合竞价同样：停板收盘价上的未匹配量进入次日。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>涨跌停把连续价格路径截断，把订单流变成配给。流动性黑洞 = 对手方供给的角点解。磁吸：接近限制时方向交易加速，因交易者担心被锁在外面或里面。冷却假说在 A 股日常样本中较弱，因为信息仍在隔夜积累，T+1 又禁止当日用反向交易纠错。于是黑洞的持续时间可以是多个交易日。</p><p>与工程课连接：这不是撮合核故障，核在按规则工作。故障课的「不确定成交」与这里的「确定不可成交」不同，监控原因码必须分开。</p>',11)),(e(),i(r,null,{default:E(()=>[o(B,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20Flow%5B%22%E8%AE%A2%E5%8D%95%E6%B5%81%22%5D%20--%3E%20Band%5B%22%E6%B6%A8%E8%B7%8C%E5%B9%85%E8%B5%B0%E5%BB%8A%22%5D%0A%20%20Band%20--%3E%7C%22%E8%B6%8A%E5%87%BA%22%7C%20Lock%5B%22%E4%B8%80%E4%BE%A7%E7%B0%BF%E6%B6%88%E5%A4%B1%22%5D%0A%20%20Lock%20--%3E%20Ration%5B%22%E6%97%B6%E9%97%B4%E4%BC%98%E5%85%88%E9%85%8D%E7%BB%99%22%5D%0A%20%20Ration%20--%3E%20Next%5B%22%E6%AC%A1%E6%97%A5%E5%BC%80%E7%9B%98%E9%9B%86%E5%90%88%E7%AB%9E%E4%BB%B7%22%5D%0A%20%20Next%20--%3E%20Lock%0A%20%20Fut%5B%22%E6%9C%9F%E8%B4%A7%E4%BB%8D%E4%BA%A4%E6%98%93%22%5D%20--%3E%20Gap%5B%22%E5%9F%BA%E5%B7%AE%E7%BC%BA%E8%85%BF%22%5D%0A%20%20Lock%20--%3E%20Gap%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不提供封板、撤单诱多空或利用停牌配合涨跌停的操纵方法。规则以交易所现行交易规则为准。本课对象是竞价股票；债券、基金有不同限制。</p><p><span class="marginnote">这一步若做错——把锁定日的收盘价当可成交价记账——组合净值会在连续跌停区间系统性高估流动性，回撤与保证金测算全部失真；2015 年一些「市场中性」产品的假净值正是从这里来的。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>锁定后流动性是配给，收盘价可不可实现必须分侧。</li><li>延迟发现把风险推到次日拍卖；T+1 禁止当日纠错。</li><li>2015 年路径是涨跌停 + 两融强平，中性缺腿。</li><li>出处：上交所交易规则；Kim and Rhee, <em>JF</em>, 1997；本栏涨跌停与邻近课。</li></ul>',5))])}const C=l(d,[["render",p]]);export{q as __pageData,C as default};
